      echo " _   _  ___ | | ___ (_)_  _____  ___ "
      echo "| | | |/ _ \\| |/ _ \\| \\ \\/ / _ \\/ __|"
      echo "| |_| | (_) | | (_) | |>  < (_) \\__ \\"
      echo " \__, |\___/|_|\___/|_/_/\\_\___/|___/"
      echo " |___/                               "
      echo -e "\033[0m"

