      if [ "$PWD" = "$HOME" ] && [ -d "$HOME/src" ]; then
        repos=("$HOME/src"/*)
        if [ ''${#repos[@]} -eq 1 ] && [ -d "''${repos[0]}" ]; then
          cd "''${repos[0]}"
        fi
      fi
    '';
  };

